const n=i=>Math.max(1,...i.filter(t=>t>0)),r=(i,t)=>i===0?100:Math.max(5,Math.round(i/t*100)),s=(i,t)=>{const a=Number.isFinite(t)&&t>0?t:5e3;return Math.max(1,...i.map(e=>e===0?a:e).filter(Number.isFinite))},c=(i,t)=>Number.isFinite(i)&&Number.isFinite(t)&&t>0?Math.min(100,Math.max(0,i/t*100)):0,o=(i,t=10)=>[...Array(Math.max(0,t-i.length)).fill(null),...i.slice(0,t)];export{n as a,o as b,c as d,s as l,r as s};
